import { AnchorHTMLAttributes, forwardRef, ReactNode, Ref } from 'react';

export interface Props extends AnchorHTMLAttributes<HTMLAnchorElement> {
    url?: string;
    target?: string;
    rel?: string;
    children?: ReactNode;
}

const Href = (
    { url = '#', target = '_blank', rel = 'noopener noreferrer nofollow', children, ...rest }: Props,
    ref: Ref<HTMLAnchorElement>
) => (
    <a href={url} target={target} rel={rel} ref={ref} {...rest}>
        {children}
    </a>
);

export default forwardRef<HTMLAnchorElement, Props>(Href);
import { render } from '@testing-library/react';

import Href from './Href';

describe('Href component', () => {
    const url = 'https://protonmail.com';
    const text = 'panda';

    it('should render a link with proper attributes', () => {
        const { getByText } = render(<Href url={url}>{text}</Href>);
        const linkNode = getByText(text);

        expect(linkNode.getAttribute('href')).toBe(url);
        expect(linkNode.getAttribute('target')).toBe('_blank');
        expect(linkNode.getAttribute('rel')).toBe('noopener noreferrer nofollow');
    });
});
module.exports = {
    setupFilesAfterEnv: ['./jest.setup.js'],
    moduleDirectories: ['<rootDir>/node_modules', 'node_modules'],
    collectCoverage: true,
    collectCoverageFrom: ['src/**/*.{js,jsx,ts,tsx}'],
    testEnvironment: './jest.env.js',
    transformIgnorePatterns: [
        'node_modules/(?!(@proton/shared|@proton/components|@protontech/mutex-browser|pmcrypto|@protontech/bip39)/)',
    ],
    transform: {
        '^.+\\.(js|tsx?)$': '<rootDir>/jest.transform.js',
    },
    moduleNameMapper: {
        '\\.(jpg|jpeg|png|gif|eot|otf|webp|svg|ttf|woff|woff2|mp4|webm)$': '@proton/components/__mocks__/fileMock.js',
        '\\.(css|scss|less)$': '@proton/components/__mocks__/styleMock.js',
        '\\.(md)$': '<rootDir>/src/__mocks__/mdMock.ts',
        '@protontech/sieve.js': '@proton/components/__mocks__/sieve.js',
    },
    reporters: ['default', ['jest-junit', { outputName: 'test-report.xml' }]],
    coverageReporters: ['text', 'lcov', 'cobertura'],
};
import { render } from '@testing-library/react';

import Alert from './Alert';

describe('Alert component', () => {
    const text = 'Panda';
    const learnMoreText = 'Learn more';
    const { container } = render(
        <Alert className="mb1" learnMore="https://protonmail.com">
            {text}
        </Alert>
    );
    const { firstChild } = container;

    it('renders children and should contain "Learn more" link', () => {
        expect(firstChild.textContent).toBe(`${text}${learnMoreText}`);
    });

    it('has default class', () => {
        expect(firstChild).toHaveClass('mb1 alert-block');
    });

    it('should have error class for warning type', () => {
        const { container } = render(
            <Alert className="mb1" type="warning">
                {text}
            </Alert>
        );
        expect(container.firstChild).toHaveClass('mb1 alert-block--warning');
    });
});

